from enum import Enum
class TradeDirection(str, Enum): BUY="BUY"; SELL="SELL"
class AdmissionStatus(str, Enum): ADMITTED="ADMITTED"; BLOCKED="BLOCKED"
class GeometryStatus(str, Enum): READY="READY"; BLOCKED="BLOCKED"
class PlanState(str, Enum): CREATED="CREATED"; READY="READY"; REVALIDATED="REVALIDATED"; BLOCKED="BLOCKED"; SUPERSEDED="SUPERSEDED"
class QuotaState(str, Enum): AVAILABLE="AVAILABLE"; RESERVED="RESERVED"; CONSUMED="CONSUMED"; RELEASED="RELEASED"
class ReservationFinality(str, Enum): PROVISIONAL="PROVISIONAL"; FINAL="FINAL"
class PaperConsumeEvent(str, Enum): UNSET="UNSET"; PLAN_CREATED="PLAN_CREATED"; ORDER_ATTEMPTED="ORDER_ATTEMPTED"; ORDER_ACCEPTED="ORDER_ACCEPTED"; FIRST_FILL="FIRST_FILL"
class PaperPolicyProfile(str, Enum):
    UNSET="UNSET"; PLAN_CREATED="PLAN_CREATED"; ORDER_ATTEMPTED="ORDER_ATTEMPTED"; ORDER_ACCEPTED="ORDER_ACCEPTED"; FILLED="FILLED"; TWO_STAGE_ACCEPTED="TWO_STAGE_ACCEPTED"; TWO_STAGE_FILLED="TWO_STAGE_FILLED"
class OrderState(str, Enum): CREATED="CREATED"; VALIDATED="VALIDATED"; ATTEMPTED="ATTEMPTED"; ACCEPTED="ACCEPTED"; PARTIALLY_FILLED="PARTIALLY_FILLED"; FILLED="FILLED"; REJECTED="REJECTED"; CANCELLED="CANCELLED"
class PositionState(str, Enum): OPEN="OPEN"; CLOSED_STOP="CLOSED_STOP"; CLOSED_TARGET="CLOSED_TARGET"; CLOSED_SESSION="CLOSED_SESSION"; CLOSED_MANUAL_SIM="CLOSED_MANUAL_SIM"
class PaperScenario(str, Enum): IMMEDIATE_FILL="IMMEDIATE_FILL"; REJECT_AT_ATTEMPT="REJECT_AT_ATTEMPT"; ACCEPT_THEN_CANCEL="ACCEPT_THEN_CANCEL"; PARTIAL_THEN_FILL="PARTIAL_THEN_FILL"; QUOTE_UNAVAILABLE="QUOTE_UNAVAILABLE"; GEOMETRY_DRIFT="GEOMETRY_DRIFT"
class LedgerEventType(str, Enum): PLAN_CREATED="PLAN_CREATED"; PLAN_REVALIDATED="PLAN_REVALIDATED"; PLAN_BLOCKED="PLAN_BLOCKED"; QUOTA_RESERVED="QUOTA_RESERVED"; QUOTA_CONSUMED="QUOTA_CONSUMED"; QUOTA_RELEASED="QUOTA_RELEASED"; ORDER_CREATED="ORDER_CREATED"; ORDER_VALIDATED="ORDER_VALIDATED"; ORDER_ATTEMPTED="ORDER_ATTEMPTED"; ORDER_ACCEPTED="ORDER_ACCEPTED"; ORDER_PARTIAL_FILL="ORDER_PARTIAL_FILL"; ORDER_FILLED="ORDER_FILLED"; ORDER_REJECTED="ORDER_REJECTED"; ORDER_CANCELLED="ORDER_CANCELLED"; POSITION_OPENED="POSITION_OPENED"; POSITION_CLOSED="POSITION_CLOSED"; RECONCILED="RECONCILED"; DUPLICATE_IGNORED="DUPLICATE_IGNORED"
class RevalidationDisposition(str, Enum): UNCHANGED="UNCHANGED"; REPRICED="REPRICED"; BLOCKED="BLOCKED"
class CheckpointDisposition(str, Enum): ACCEPTED="ACCEPTED"; REJECT_VERSION="REJECT_VERSION"; REJECT_CONFIG="REJECT_CONFIG"; REJECT_HASH="REJECT_HASH"; REBUILD_REQUIRED="REBUILD_REQUIRED"
class HealthState(str, Enum): READY="READY"; DEGRADED="DEGRADED"; BLOCKED="BLOCKED"
class AcceptanceStatus(str, Enum): PASS="PASS"; FAIL="FAIL"; PENDING="PENDING"; BLOCKED="BLOCKED"
